import time
from openai import OpenAI

client = OpenAI(base_url="http://localhost:8000/v1", api_key="EMPTY")

def measure(prompt, model, max_tokens=256):
    t0 = time.perf_counter()
    ttft, last, n_tokens, itls = None, None, 0, []
    stream = client.chat.completions.create(
        model=model, messages=[{"role": "user", "content": prompt}],
        max_tokens=max_tokens, stream=True)
    for chunk in stream:
        if not chunk.choices or not chunk.choices[0].delta.content:
            continue
        now = time.perf_counter()
        if ttft is None:
            ttft = now - t0            # TTFT: request sent -> first token
        else:
            itls.append(now - last)    # ITL: gap between consecutive tokens
        last, n_tokens = now, n_tokens + 1
    e2el = last - t0
    tpot = (e2el - ttft) / max(n_tokens - 1, 1)   # TPOT = (E2EL - TTFT) / (N - 1)
    return {"ttft_s": ttft, "tpot_s": tpot, "e2el_s": e2el,
            "tokens": n_tokens, "mean_itl_s": sum(itls) / max(len(itls), 1)}

GPU_VRAM_GB = {"L4": 24, "A100": 80, "H100": 80, "H200": 141, "B200": 192}

def serving_memory_gb(params_b, bits=16, overhead=0.20):
    """Memory (GB) = P * (Q / 8) * (1 + Overhead)   (rough sizing shortcut)."""
    return params_b * (bits / 8) * (1 + overhead)

def gpus_needed(params_b, bits, gpu, overhead=0.20, mem_util=0.90):
    need = serving_memory_gb(params_b, bits, overhead)
    usable = GPU_VRAM_GB[gpu] * mem_util      # e.g. --gpu-memory-utilization 0.90
    return need, int(-(-need // usable))      # ceiling division

if __name__ == "__main__":
    for p, q in [(7, 16), (7, 8), (70, 16), (70, 8), (70, 4)]:
        need, n = gpus_needed(p, q, "H100")
        print(f"{p:>3}B @ {q:>2}-bit: {need:6.1f} GB -> {n} x H100 (80 GB)")
# Output:
#   7B @ 16-bit:   16.8 GB -> 1 x H100 (80 GB)
#   7B @  8-bit:    8.4 GB -> 1 x H100 (80 GB)
#  70B @ 16-bit:  168.0 GB -> 3 x H100 (80 GB)
#  70B @  8-bit:   84.0 GB -> 2 x H100 (80 GB)
#  70B @  4-bit:   42.0 GB -> 1 x H100 (80 GB)
